CREATE TABLE users(id BIGINT NOT NULL, username VARCHAR(255) NOT NULL, name VARCHAR(255) NOT NULL, email VARCHAR(255) NOT NULL, hash VARCHAR(64) NOT NULL, salt VARCHAR(16) NOT NULL, admin BOOLEAN NOT NULL DEFAULT false, can_create_groups BOOLEAN NOT NULL DEFAULT false, can_create_repositories BOOLEAN NOT NULL DEFAULT false, avatar BLOB(16 M), notifications INT NOT NULL DEFAULT 0)
CREATE TABLE teams(id BIGINT NOT NULL, teamname VARCHAR(255) NOT NULL, name VARCHAR(255) NOT NULL, avatar BLOB(16 M))
CREATE TABLE team_users(f_team BIGINT NOT NULL, f_user BIGINT NOT NULL)
CREATE TABLE memberships(id BIGINT NOT NULL, f_user BIGINT, f_team BIGINT, member_of VARCHAR(255) NOT NULL, role VARCHAR(255) NOT NULL)
